<?php
ob_start();
require __DIR__.'/shared_components.php';
use Quill\services\editor\DetachedComponentDocument;
use Quill\services\editor\EditorDocumentMapper;
use Quill\services\editor\EditorContentSource;
use Quill\services\conversion\quillToUrpc\QuillToUrpcConverter;

$startDetach=$count;
$component=loadedComponent($sharedId);
$before=$component->component_json;$version=$component->lock_version;
$rows=$pdo->query('SELECT COUNT(*) FROM quill_block')->fetchColumn();
$prepared=(new DetachedComponentDocument())->create($component,'qc-detach-test');$local=$prepared['document'];
check($local->sections[0]->blocks[0]->descriptor->name==='section'&&!isset($local->sections[0]->blocks[0]->_quill->component),'Detachment returns real editable blocks without a component wrapper');
check($local->sections[0]->blocks[0]->children[0]->content==='Newer working source','The local copy uses the displayed working component content');
check(count($local->settings->actions)===1&&$local->settings->actions[0]->id!=='qa-component','Component actions are copied with isolated identities');
$action=$local->settings->actions[0];
check($local->sections[0]->blocks[0]->children[0]->_quill->editor->onClick===$action->id,'Editable event metadata remains connected to the copied action');
check($action->steps[0]->target->value===$local->sections[0]->blocks[0]->children[1]->_quill->editor->actionTargetId,'Local action targets point into the detached copy');
check($prepared['targetMap']->{'qt-component'}===$action->steps[0]->target->value,'External page actions can be remapped to the local target');
check(in_array('component.css',$local->assets->styles,true)&&in_array('component.js',$local->assets->scripts,true),'Detaching preserves component dependency assets');
check(loadedComponent($sharedId)->component_json===$before&&loadedComponent($sharedId)->lock_version===$version&&$pdo->query('SELECT COUNT(*) FROM quill_block')->fetchColumn()===$rows,'Preparing local blocks does not write or delete source rows');
$mapped=(new EditorDocumentMapper())->map($local,new stdClass());
check((new QuillToUrpcConverter())->convert(new EditorContentSource($mapped->document,$mapped->blocks))->actions[0]->id===$action->id,'Prepared blocks and actions survive the real mapper and conversion pipeline');

$leaf=$element('div','Responsive copy');
$leaf['_quill']->styles=(object)['base'=>(object)['color'=>'#123456'],'mobile'=>(object)['padding'=>'9px']];
$doc=sharedDocument([$leaf],'Responsive component');$doc->settings->breakpoints=(object)['tablet'=>960,'mobile'=>520];
$definition=(object)['id'=>'qanim-legacy','name'=>'Fade','duration'=>100,'delay'=>0,'iterations'=>1,'direction'=>'normal','fillMode'=>'both','easing'=>'linear','tracks'=>(object)['opacity'=>[(object)['time'=>0,'value'=>'0'],(object)['time'=>100,'value'=>'1']]]];
$doc->settings->animations=(object)['qanim-legacy'=>$definition];$doc->settings->animation_bindings=[(object)['id'=>'qbind-legacy','animationId'=>'qanim-legacy','trigger'=>'load','target'=>(object)['section'=>'main','path'=>[0]]]];
$new=request('createEditorComponent',['_token'=>'test-csrf','name'=>'Responsive component','document'=>json_encode($doc)],201)['component'];
$outerDoc=sharedDocument([sharedNode($new['id'],'qc-inner-a'),sharedNode($new['id'],'qc-inner-b')],'Nested local copy');
$outer=request('component',['_token'=>'test-csrf','name'=>'Multi-root shared component'],201);
$outerModel=loadedComponent($outer['id']);
(new Quill\services\editor\EditorDocumentSaver())->save($outerModel,$outerDoc,$outerModel->lock_version,'draft',1);
$nestedLocal=(new DetachedComponentDocument())->create(loadedComponent($outer['id']),'qc-nested-detach')['document'];
check(count($nestedLocal->sections[0]->blocks)===2,'Multi-root and nested components flatten into their original sibling blocks');
check(!isset($nestedLocal->sections[0]->blocks[0]->_quill->component)&&!isset($nestedLocal->sections[0]->blocks[1]->_quill->component),'Nested component links are also detached');
check($nestedLocal->sections[0]->blocks[0]->_quill->editor->styleBreakpoints->mobile===520,'Original component breakpoints are retained on local editable blocks');
check(count(get_object_vars($nestedLocal->settings->animations))===2&&count($nestedLocal->settings->animation_bindings)===2,'Nested legacy animation resources are copied without identity collisions');
check($nestedLocal->settings->animation_bindings[0]->target->path===[0]&&$nestedLocal->settings->animation_bindings[1]->target->path===[1],'Legacy animation targets are rebased onto flattened blocks');
$nestedLocal->settings->breakpoints=(object)['tablet'=>1100,'mobile'=>700];
$mapped=(new EditorDocumentMapper())->map($nestedLocal,new stdClass());
$result=(new QuillToUrpcConverter())->convert(new EditorContentSource($mapped->document,$mapped->blocks));
check(str_contains($result->scopedCss,'max-width: 520px')&&!str_contains($result->scopedCss,'max-width: 700px'),'Detached responsive styles keep source thresholds even on a page with different breakpoints');
check(!str_contains(json_encode($nestedLocal),'quill-scope-'),'Generated preview scope classes are not persisted in the local copy');

$host=request('page',['_token'=>'test-csrf','name'=>'Detached copy host'],201);
$hostModel=loadedPage($host['id']);
(new Quill\services\editor\EditorDocumentSaver())->save($hostModel,$nestedLocal,$hostModel->lock_version,'publish',1);
$reopened=(new Quill\services\editor\EditorDocumentLoader())->load(loadedPage($host['id']))['document'];
check(count($reopened->sections[0]->blocks)===2&&!isset($reopened->sections[0]->blocks[0]->_quill->component),'Saved and reopened local copies are ordinary page-owned blocks');
check($reopened->sections[0]->blocks[0]->_quill->editor->styleBreakpoints->mobile===520&&count($reopened->settings->animation_bindings)===2,'Responsive metadata and legacy animations survive Save/Publish/Reopen');
check(loadedComponent($sharedId)->component_json===$before&&loadedComponent($sharedId)->lock_version===$version,'Publishing a local copy leaves the source component unchanged');

$_GET=['instance'=>'qc-endpoint-test','version'=>(string)$component->lock_version];$_SERVER['REQUEST_METHOD']='GET';
$response=$controller->detachedEditorComponent(['id'=>(string)$sharedId]);
check((new ReflectionProperty(response\Response::class,'statusCode'))->getValue($response)===200,'Read-only authenticated detach endpoint prepares a local block');
$_GET['version']='999999';$response=$controller->detachedEditorComponent(['id'=>(string)$sharedId]);
check((new ReflectionProperty(response\Response::class,'statusCode'))->getValue($response)===409,'Stale component versions are rejected without writing');
$_GET=['instance'=>'bad-instance','version'=>(string)$component->lock_version];$response=$controller->detachedEditorComponent(['id'=>(string)$sharedId]);
check((new ReflectionProperty(response\Response::class,'statusCode'))->getValue($response)===422,'Invalid instance identities are rejected');
$_GET=[];
echo 'Passed '.($count-$startDetach)." component-to-local-block checks.\n";ob_end_flush();
